      "rawText": "9月21日，在蔚来全新ES8上市一周年之际，蔚来联合创始人、总裁秦力洪在北京未来科学城蔚来体验中心，向第150000台全新ES8用户、中国首位兼具大洋深潜与极地科考经历的浙大地质学博士唐立梅交付新车，她曾随“蛟龙”号下潜2774米深海，随“雪龙”号完成165天南极科考。2026年8月全新ES8零售销量达10991台，蝉联大型SUV和40万级车型销量第一，还以85.3分位列2026上半年所有纯电车型NPS第一。其推动大型SUV向纯电转型，2026年1-8月纯电大三排SUV累计销量25.99万台居各动力形式第一，同年8月纯电大五座SUV销量首超增程登顶，实现连续5个月环比增长。(AI生成)",
      "relatedTitles": [
        "蔚来：全新ES8上市一周年实现累计交付15万台"
      ],
